export default function HomePage() {

  useEffect(() => {
    const gallery = document.querySelector<HTMLElement>('.hero-photo');
    if (!gallery) return;
    const slides = Array.from(gallery.querySelectorAll<HTMLImageElement>('.hero-slide'));
    const caption = gallery.querySelector<HTMLElement>('.slide-caption');
    let index = 0;
    const timer = window.setInterval(() => {
      if (document.hidden || slides.length < 2) return;
      index = (index + 1) % slides.length;
      slides.forEach((slide, i) => {
        slide.classList.toggle('is-active', i === index);
        slide.setAttribute('aria-hidden', String(i !== index));
      });
      if (caption) caption.textContent = slides[index].dataset.caption || '';
    }, 3000);
    return () => window.clearInterval(timer);
  }, []);

 return <div dangerouslySetInnerHTML={{ __html: companyMarkup }} />;
}



